# controller-backup-manifest.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd32/schemas/controller-backup-manifest.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "properties": {
    "backup_id": {
      "pattern": "^cb-[A-Za-z0-9._-]+$",
      "type": "string"
    },
    "captured_at": {
      "format": "date-time",
      "type": "string"
    },
    "commit_high_water": {
      "minimum": 1,
      "type": "integer"
    },
    "credential_references": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "issuer": {
            "minLength": 1,
            "type": "string"
          },
          "namespace": {
            "minLength": 1,
            "type": "string"
          },
          "reference_id": {
            "minLength": 1,
            "type": "string"
          },
          "scope_digest": {
            "pattern": "^sha256:[0-9a-f]{64}$",
            "type": "string"
          },
          "status": {
            "enum": [
              "unresolved",
              "reattached",
              "revoked",
              "expired"
            ]
          },
          "version_or_generation": {
            "minLength": 1,
            "type": "string"
          }
        },
        "required": [
          "issuer",
          "namespace",
          "reference_id",
          "version_or_generation",
          "scope_digest",
          "status"
        ],
        "type": "object"
      },
      "type": "array"
    },
    "integrity": {
      "additionalProperties": false,
      "properties": {
        "algorithm": {
          "const": "SHA-256"
        },
        "equal_revision_conflicts": {
          "const": 0
        },
        "manifest_self_verified": {
          "const": true
        },
        "objects_verified": {
          "const": true
        },
        "secret_scan": {
          "const": "passed"
        }
      },
      "required": [
        "algorithm",
        "manifest_self_verified",
        "objects_verified",
        "secret_scan",
        "equal_revision_conflicts"
      ],
      "type": "object"
    },
    "record_families": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "digest": {
            "pattern": "^sha256:[0-9a-f]{64}$",
            "type": "string"
          },
          "gaps": {
            "items": {
              "type": "string"
            },
            "type": "array"
          },
          "high_water": {
            "minimum": 0,
            "type": "integer"
          },
          "name": {
            "enum": [
              "coordination",
              "tickets_workflows",
              "dispatch_execution",
              "grants_policy",
              "configuration_identity",
              "assets",
              "archive_indexes",
              "recovery_retention",
              "credential_references"
            ]
          },
          "namespace": {
            "minLength": 1,
            "type": "string"
          },
          "object_count": {
            "minimum": 0,
            "type": "integer"
          }
        },
        "required": [
          "name",
          "namespace",
          "high_water",
          "object_count",
          "digest",
          "gaps"
        ],
        "type": "object"
      },
      "minItems": 9,
      "type": "array"
    },
    "remote_work_observations": {
      "items": {
        "additionalProperties": false,
        "properties": {
          "attempt_id": {
            "minLength": 1,
            "type": "string"
          },
          "capacity_decision": {
            "enum": [
              "held",
              "released",
              "not_applicable"
            ]
          },
          "classification": {
            "enum": [
              "proven-running",
              "proven-stopped",
              "unreachable",
              "uncertain"
            ]
          },
          "evidence_refs": {
            "items": {
              "type": "string"
            },
            "type": "array"
          }
        },
        "required": [
          "attempt_id",
          "classification",
          "capacity_decision",
          "evidence_refs"
        ],
        "type": "object"
      },
      "type": "array"
    },
    "retention": {
      "additionalProperties": false,
      "properties": {
        "holds_preserved": {
          "const": true
        },
        "policy_revision": {
          "minLength": 1,
          "type": "string"
        },
        "retention_until": {
          "format": "date-time",
          "type": "string"
        }
      },
      "required": [
        "policy_revision",
        "retention_until",
        "holds_preserved"
      ],
      "type": "object"
    },
    "rpo": {
      "additionalProperties": false,
      "properties": {
        "target_seconds": {
