        }
      },
      "required": [
        "target_seconds",
        "dispatch_blocked_until_gates"
      ],
      "type": "object"
    },
    "schema_version": {
      "const": 1
    },
    "snapshot_boundary": {
      "additionalProperties": false,
      "properties": {
        "consistent": {
          "const": true
        },
        "marker_id": {
          "minLength": 1,
          "type": "string"
        },
        "mode": {
          "enum": [
