      },
      "required": [
        "controller_id",
        "boot_id",
        "fence_epoch"
      ],
      "type": "object"
    },
    "state": {
      "enum": [
        "staging",
        "verified",
        "failed",
        "expired"
      ]
    },
    "target": {
      "additionalProperties": false,
      "properties": {
        "failure_domain": {
          "minLength": 1,
          "type": "string"
        },
        "independent_readback": {
          "const": true
