        "manifest_digest": {
          "pattern": "^sha256:[0-9a-f]{64}$",
          "type": "string"
        },
        "target_id": {
          "minLength": 1,
          "type": "string"
        }
      },
      "required": [
        "target_id",
        "failure_domain",
        "independent_readback",
        "manifest_digest"
      ],
      "type": "object"
