    "backup_id",
    "state",
    "source_controller",
    "captured_at",
    "commit_high_water",
    "snapshot_boundary",
    "rpo",
    "rto",
    "target",
    "record_families",
    "credential_references",
    "retention",
    "integrity",
    "remote_work_observations"
  ],
  "title": "CHD controller backup manifest",
  "type": "object"
}
